import { Component } from './base/Component';
import { ensureElement } from '../utils/utils';
export class Basket extends Component {
    constructor(container, events, basketData) {
        super(container);
        this.events = events;
        this.counter = ensureElement('.header__basket-counter');
        this.totalPrice = ensureElement('.basket__price', container);
        this.basketList = ensureElement('.basket__list', container);
        this.basketButton = ensureElement('.basket__button', container);
        const headerBasketButton = ensureElement('.header__basket');
        headerBasketButton.addEventListener('click', () => {
            this.events.emit('busket:open', { ids: basketData.items });
        });
        this.basketButton.addEventListener('click', () => {
            if (basketData.items.length > 0) {
                this.events.emit('order:open');
            }
        });
    }
    set items(items) {
        this.counter.textContent = String(items.length);
        this.basketButton.disabled = items.length === 0;
    }
    set total(total) {
        this.totalPrice.textContent = `${total} синапсов`;
    }
    get busketList() {
        return this.basketList;
    }
    getContainer() {
        return this.container;
    }
}
